alter table public.webhook_integrations add column if not exists secret_prefix text, add column if not exists last_used_at timestamptz, add column if not exists last_event_at timestamptz, add column if not exists event_count bigint not null default 0; create index if not exists webhook_integrations_endpoint_active_idx on public.webhook_integrations(endpoint_key) where status='active'; create or replace function public.touch_webhook_integration(p_endpoint_key text) returns void language plpgsql security definer set search_path=public as $$ begin update public.webhook_integrations set last_used_at=now(),last_event_at=now(),event_count=event_count+1,updated_at=now() where endpoint_key=p_endpoint_key and status='active'; end; $$; revoke execute on function public.touch_webhook_integration(text) from public,anon,authenticated; grant execute on function public.touch_webhook_integration(text) to service_role;